/*
 * Market indicators panel (dashboard): US Treasury yields, VIX, crude oil, CNN Fear & Greed, AAII sentiment.
 * Data: window.MARKET_DATA (js/marketData.js, generated by scripts/fetch-market-data.mjs) or the
 * MOCK_MARKET fallback, exposed as UMB.state.market. Colors come from CSS variables in index.html
 * (--bear / --neutral / --bull diverging scale, --spark for single-series lines).
 */
(function () {
  'use strict';
  const U = window.UMB;
  const { esc, ui } = U;

  const sparks = new Map(); // id → { points:[{date,v}], label, fmt }
  let seq = 0;
  let root = null;
  let handlers = null;

  const lastOf = (a) => (a && a.length ? a[a.length - 1] : null);
  const prevOf = (a) => (a && a.length > 1 ? a[a.length - 2] : null);
  const fixed = (v, d = 2) => (v == null || Number.isNaN(v) ? '-' : Number(v).toFixed(d));
  const signed = (v, d = 2) => (v == null || Number.isNaN(v) ? '-' : `${v > 0 ? '+' : v < 0 ? '−' : '±'}${Math.abs(v).toFixed(d)}`);
  const shortDate = (k) => { const [, m, d] = String(k).split('-'); return `${Number(m)}/${Number(d)}`; };
  const kstStamp = (iso) => new Date(iso).toLocaleString('ko-KR', { timeZone: 'Asia/Seoul', month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' });

  // Change chip: arrow + value in text ink (direction is not good/bad for yields or oil).
  const delta = (v, unit, d = 2) => (v == null ? '' : `<span class="font-mono text-xs text-slate-500 dark:text-slate-400">${v > 0 ? '▲' : v < 0 ? '▼' : '■'} ${signed(v, d).replace(/^[+−±]/, '')}${unit}</span>`);

  // ---------- sparkline (single series → no legend; card title names it) ----------
  function sparkline(points, { label, fmt, ref = null, refLabel = '' }) {
    const pts = (points || []).filter((p) => p.v != null && !Number.isNaN(p.v));
    if (pts.length < 2) return '<div class="h-10"></div>';
    const id = `spark-${++seq}`;
    const W = 100, H = 40, pad = 3;
    const vals = pts.map((p) => p.v).concat(ref == null ? [] : [ref]);
    let min = Math.min(...vals), max = Math.max(...vals);
    if (min === max) { min -= 1; max += 1; }
    const x = (i) => (i / (pts.length - 1)) * W;
    const y = (v) => pad + ((max - v) / (max - min)) * (H - 2 * pad);
    sparks.set(id, { points: pts, label, fmt, yPct: pts.map((p) => (y(p.v) / H) * 100) });
    const line = pts.map((p, i) => `${i ? 'L' : 'M'}${x(i).toFixed(2)},${y(p.v).toFixed(2)}`).join('');
    const area = `${line}L${W},${H}L0,${H}Z`;
    const end = pts[pts.length - 1];
    const refLine = ref == null ? '' : `<line x1="0" x2="${W}" y1="${y(ref).toFixed(2)}" y2="${y(ref).toFixed(2)}" stroke="currentColor" class="text-slate-400 dark:text-slate-500" stroke-dasharray="3 3" vector-effect="non-scaling-stroke" stroke-width="1"/>`;
    // Dots and crosshair are HTML (percent-positioned) so they stay round under preserveAspectRatio="none".
    return `
      <div class="relative h-10 cursor-crosshair touch-none" data-spark="${id}" role="img"
        aria-label="${esc(label)} 최근 ${pts.length}개 관측치, 최근값 ${esc(fmt(end.v))} (${esc(end.date)})">
        <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" class="h-full w-full overflow-visible" aria-hidden="true">
          <path d="${area}" style="fill: var(--spark); opacity: .08"/>
          ${refLine}
          <path d="${line}" fill="none" style="stroke: var(--spark)" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/>
        </svg>
        ${ref == null ? '' : `<span class="pointer-events-none absolute right-0 text-[10px] text-slate-400" style="top:calc(${(y(ref) / H) * 100}% - 13px)">${esc(refLabel)}</span>`}
        <span class="pointer-events-none absolute h-2.5 w-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2" style="left:100%;top:${(y(end.v) / H) * 100}%;background:var(--spark);--tw-ring-color:var(--surface)"></span>
        <span data-cross class="pointer-events-none absolute inset-y-0 hidden w-px bg-slate-400/70"></span>
        <span data-dot class="pointer-events-none absolute hidden h-2.5 w-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2" style="background:var(--spark);--tw-ring-color:var(--surface)"></span>
      </div>
      <div class="mt-0.5 flex justify-between text-[10px] text-slate-400"><span>${esc(shortDate(pts[0].date))}</span><span>${esc(shortDate(end.date))}</span></div>`;
  }

  // ---------- card chrome ----------
  function card(title, section, body, extra = '') {
    const meta = section ? `<div class="mt-3 flex flex-wrap items-center gap-x-2 gap-y-1 border-t border-slate-100 pt-2 text-[11px] text-slate-400 dark:border-slate-800">
        ${section.stale ? ui.badge('갱신 실패 · 이전 값', 'bg-amber-100 text-amber-800 dark:bg-amber-500/15 dark:text-amber-300') : ''}
        <span>기준 ${esc(section.asOf && section.asOf.length > 10 ? kstStamp(section.asOf) + ' KST' : section.asOf || '-')}</span>
        <span>·</span>
        ${section.url ? `<a href="${esc(section.url)}" target="_blank" rel="noopener noreferrer" class="underline decoration-dotted hover:text-slate-600 dark:hover:text-slate-300">${esc(section.source || '출처')}</a>` : `<span>${esc(section.source || '')}</span>`}
      </div>` : '';
    return `<section class="flex flex-col rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900 ${extra}">
      <h3 class="mb-3 text-sm font-bold">${title}</h3>
      <div class="flex-1">${body}</div>
      ${meta}
    </section>`;
  }
  const missing = (title, key) => card(title, null,
    `<p class="py-6 text-center text-sm text-slate-500">데이터를 불러오지 못했습니다.${(U.state.market?.errors || {})[key] ? `<br><span class="text-xs">${esc(U.state.market.errors[key])}</span>` : ''}</p>`);

  // ---------- 1. Treasury yields ----------
  const CURVE = { bear_steepening: '베어 스티프닝', bull_steepening: '불 스티프닝', bear_flattening: '베어 플래트닝', bull_flattening: '불 플래트닝' };

  function ratesCard(r) {
    if (!r || !r.series) return missing('미국 국채 금리', 'rates');
    const rows = [['y3m', '3개월'], ['y2', '2년'], ['y10', '10년'], ['y30', '30년']]
      .filter(([k]) => r.series[k] && r.series[k].length)
      .map(([k, label]) => {
        const s = r.series[k];
        const cur = lastOf(s), prev = prevOf(s);
        const bp = prev ? Math.round((cur.value - prev.value) * 100) : null;
        return `<li class="grid grid-cols-[3.5rem_4.5rem_1fr] items-center gap-3">
          <div><p class="text-xs text-slate-500">${label}</p>${delta(bp, 'bp', 0)}</div>
          <p class="font-mono text-lg font-bold tabular-nums">${fixed(cur.value)}<span class="text-xs font-normal text-slate-500">%</span></p>
          <div>${sparkline(s.map((p) => ({ date: p.date, v: p.value })), { label: `미 국채 ${label}물`, fmt: (v) => `${v.toFixed(2)}%` })}</div>
        </li>`;
      }).join('');
    const y2 = lastOf(r.series.y2), y10 = lastOf(r.series.y10);
    const spread = r.latest?.spread_2s10s_bp ?? (y2 && y10 ? Math.round((y10.value - y2.value) * 100) : null);
    const p2 = prevOf(r.series.y2), p10 = prevOf(r.series.y10);
    const dSpread = r.latest?.d_spread_2s10s_bp ?? (p2 && p10 && spread != null ? spread - Math.round((p10.value - p2.value) * 100) : null);
    const curve = CURVE[r.latest?.curve];
    const foot = spread == null ? '' : `<div class="mt-3 flex flex-wrap items-center gap-2 rounded-xl bg-slate-50 px-3 py-2 text-sm dark:bg-slate-800/60">
        <span class="text-slate-500">2s10s 스프레드</span>
        <b class="font-mono tabular-nums">${signed(spread, 0)}bp</b>
        ${delta(dSpread, 'bp', 0)}
        ${spread < 0 ? ui.badge('장단기 금리 역전', 'bg-slate-200 text-slate-700 dark:bg-slate-700/60 dark:text-slate-200') : ''}
        ${curve ? ui.badge(curve, 'bg-slate-200 text-slate-700 dark:bg-slate-700/60 dark:text-slate-200') : ''}
      </div>`;
    return card('🏦 미국 국채 금리', r, `<ul class="space-y-3">${rows}</ul>${foot}`);
  }

  // ---------- 2. VIX ----------
  // Status palette with icon + label (never color alone).
  const VIX_REGIMES = [
    { max: 15, label: '안정', icon: '●', color: '#0ca30c' },
    { max: 20, label: '보통', icon: '■', color: '#8f8e88' },
    { max: 30, label: '경계', icon: '▲', color: '#fab219' },
    { max: Infinity, label: '공포', icon: '⚠', color: '#d03b3b' },
  ];

  function vixCard(v) {
    if (!v || !v.series || !v.series.length) return missing('VIX 변동성 지수', 'vix');
    const cur = lastOf(v.series), prev = prevOf(v.series);
    const chg = prev ? cur.close - prev.close : null;
    const pct = prev ? (chg / prev.close) * 100 : null;
    const regime = VIX_REGIMES.find((r) => cur.close < r.max);
    const body = `
      <div class="mb-3 flex items-end gap-3">
        <p class="font-mono text-4xl font-bold tabular-nums leading-none">${fixed(cur.close)}</p>
        <div class="pb-0.5">${delta(chg, '', 2)} <span class="text-xs text-slate-400">(${signed(pct, 1)}%)</span></div>
        <span class="ml-auto inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-xs font-semibold" style="border-color:${regime.color}">
          <span style="color:${regime.color}" aria-hidden="true">${regime.icon}</span>${regime.label}</span>
      </div>
      ${sparkline(v.series.map((p) => ({ date: p.date, v: p.close })), { label: 'VIX', fmt: (x) => x.toFixed(2), ref: 20, refLabel: '20' })}
      <p class="mt-2 text-xs text-slate-500">S&P 500 옵션 기반 30일 내재변동성. 20 이상이면 경계, 30 이상이면 공포 구간으로 봅니다.</p>`;
    return card('🌪 VIX 변동성 지수', v, body);
  }

  // ---------- 3. Crude oil ----------
  function oilCard(o) {
    if (!o || (!o.wti?.length && !o.brent?.length)) return missing('국제 유가', 'oil');
    const today = U.dateKey(new Date());
    const rows = [['wti', 'WTI'], ['brent', '브렌트']].filter(([k]) => o[k] && o[k].length).map(([k, label]) => {
      const s = o[k];
      const cur = lastOf(s), prev = prevOf(s);
      const pct = prev ? ((cur.close - prev.close) / prev.close) * 100 : null;
      return `<li class="grid grid-cols-[3.5rem_5rem_1fr] items-center gap-3">
        <div><p class="text-xs text-slate-500">${label}</p>${delta(pct, '%', 2)}</div>
        <p class="font-mono text-lg font-bold tabular-nums"><span class="text-xs font-normal text-slate-500">$</span>${fixed(cur.close)}</p>
        <div>${sparkline(s.map((p) => ({ date: p.date, v: p.close })), { label: `${label} 유가`, fmt: (v) => `$${v.toFixed(2)}` })}</div>
      </li>`;
    }).join('');
    const intraday = [o.wti, o.brent].some((s) => s && lastOf(s)?.date >= today);
    // Spot history (FRED, via the skill) lags ~1 week, so show the latest futures quote on top when available.
    const f = o.futures;
    // The source can skip sessions, so always state which close the change is measured against.
    const basis = (q) => { const s = q.series || []; const p = s.length > 1 ? s[s.length - 2] : null; return p ? `${shortDate(p.date)} 종가 대비` : '전일 대비'; };
    const futRow = (q, label) => (q && q.price ? `<div class="min-w-0">
        <p class="text-[11px] text-slate-500">${label} 선물</p>
        <p class="font-mono text-base font-bold tabular-nums">$${fixed(q.price)} ${delta(q.changePct, '%', 2)}</p>
        <p class="text-[10px] text-slate-400">${esc(basis(q))}</p>
      </div>` : '');
    const futures = f && (f.wti?.price || f.brent?.price) ? `
      <div class="mb-3 rounded-xl bg-slate-50 px-3 py-2 dark:bg-slate-800/60">
        <div class="grid grid-cols-2 gap-3">${futRow(f.wti, 'WTI')}${futRow(f.brent, '브렌트')}</div>
        <p class="mt-1 text-[11px] text-slate-400">최신 선물 시세 · ${esc(f.wti?.date || f.brent?.date || '')} · 아래는 현물 일별 종가</p>
      </div>` : '';
    return card('🛢 국제 유가 (배럴당)', o, `${futures}<ul class="space-y-3">${rows}</ul>
      <p class="mt-2 text-xs text-slate-500">${intraday ? '최근값은 장중 선물 가격이며 확정 종가가 아닙니다.' : `현물 일별 종가 기준${o.asOf ? ` (${esc(o.asOf)}까지)` : ''}.`}</p>`);
  }

  // ---------- 3b. Bitcoin ----------
  const krw = (v) => (v == null ? '-' : `₩${Math.round(v).toLocaleString('ko-KR')}`);
  const usd0 = (v) => (v == null ? '-' : `$${Number(v).toLocaleString('en-US', { maximumFractionDigits: 0 })}`);

  function cryptoCard(c) {
    const b = c && c.btc;
    if (!b || !b.usd) return missing('비트코인', 'crypto');
    const kimchi = b.kimchiPct == null ? '' : `<div class="flex items-center justify-between gap-2">
        <span class="text-slate-500">김치 프리미엄</span>
        <b class="font-mono tabular-nums">${signed(b.kimchiPct, 2)}%</b></div>`;
    const body = `
      <div class="mb-3 flex flex-wrap items-end gap-x-3 gap-y-1">
        <p class="font-mono text-3xl font-bold tabular-nums leading-none">${usd0(b.usd)}</p>
        <div class="pb-0.5">${delta(b.change24hPct, '%', 2)} <span class="text-xs text-slate-400">24시간</span></div>
        ${c.live ? '<span class="ml-auto inline-flex items-center gap-1 rounded-full bg-emerald-100 px-2 py-0.5 text-[11px] font-semibold text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300"><span class="h-1.5 w-1.5 animate-pulse rounded-full bg-emerald-500"></span>실시간</span>' : ''}
      </div>
      ${sparkline((b.series || []).map((p) => ({ date: p.date, v: p.close })), { label: '비트코인', fmt: (v) => usd0(v) })}
      <div class="mt-3 space-y-1.5 rounded-xl bg-slate-50 px-3 py-2 text-sm dark:bg-slate-800/60">
        <div class="flex items-center justify-between gap-2"><span class="text-slate-500">원화 환산 (글로벌)</span><b class="font-mono tabular-nums">${krw(b.krw)}</b></div>
        ${b.upbitKrw ? `<div class="flex items-center justify-between gap-2"><span class="text-slate-500">업비트 KRW-BTC</span><b class="font-mono tabular-nums">${krw(b.upbitKrw)}</b></div>` : ''}
        ${kimchi}
      </div>
      <p class="mt-2 text-xs text-slate-500">24시간 거래 · 앱이 열려 있으면 1분마다 갱신됩니다.</p>`;
    return card('₿ 비트코인 <span class="font-normal text-slate-400">BTC</span>', c, body);
  }

  // ---------- 4. CNN Fear & Greed (diverging gauge) ----------
  const FG_BANDS = [
    { from: 0, to: 25, key: 'extreme fear', label: '극단적 공포', color: 'var(--bear)' },
    { from: 25, to: 45, key: 'fear', label: '공포', color: 'var(--bear-soft)' },
    { from: 45, to: 55, key: 'neutral', label: '중립', color: 'var(--neutral)' },
    { from: 55, to: 75, key: 'greed', label: '탐욕', color: 'var(--bull-soft)' },
    { from: 75, to: 101, key: 'extreme greed', label: '극단적 탐욕', color: 'var(--bull)' },
  ];
  const fgBand = (score) => FG_BANDS.find((b) => score >= b.from && score < b.to) || FG_BANDS[FG_BANDS.length - 1];

  function arc(cx, cy, r0, r1, s0, s1) {
    const pt = (r, s) => { const a = Math.PI * (1 - s / 100); return [cx + r * Math.cos(a), cy - r * Math.sin(a)]; };
    const [x0, y0] = pt(r1, s0), [x1, y1] = pt(r1, s1), [x2, y2] = pt(r0, s1), [x3, y3] = pt(r0, s0);
    return `M${x0.toFixed(2)},${y0.toFixed(2)}A${r1},${r1} 0 0 1 ${x1.toFixed(2)},${y1.toFixed(2)}L${x2.toFixed(2)},${y2.toFixed(2)}A${r0},${r0} 0 0 0 ${x3.toFixed(2)},${y3.toFixed(2)}Z`;
  }

  function fearGreedCard(f) {
    if (!f || f.score == null) return missing('CNN 공포·탐욕 지수', 'fearGreed');
    const band = fgBand(f.score);
    const GAP = 0.7; // ≈2px surface gap between bands
    const bands = FG_BANDS.map((b) => `<path d="${arc(100, 100, 62, 92, b.from + (b.from ? GAP : 0), Math.min(b.to, 100) - (b.to < 100 ? GAP : 0))}"
        style="fill:${b.color}" data-tip="${esc(`${b.label} (${b.from}–${Math.min(b.to, 100)})`)}"/>`).join('');
    const a = Math.PI * (1 - f.score / 100);
    const nx = 100 + 80 * Math.cos(a), ny = 100 - 80 * Math.sin(a);
    const prevRow = (label, v) => (v == null ? '' : `<li class="flex items-center justify-between gap-2"><span class="text-slate-500">${label}</span>
        <span><b class="font-mono tabular-nums">${Math.round(v)}</b> <span class="text-xs text-slate-500">${fgBand(v).label}</span></span></li>`);
    const hist = (f.history || []).map((p) => ({ date: p.date, v: p.score }));
    const body = `
      <div class="grid items-center gap-4 sm:grid-cols-[minmax(0,13rem)_1fr]">
        <div class="relative mx-auto w-full max-w-[13rem]">
          <svg viewBox="0 0 200 108" class="w-full" role="img" aria-label="공포·탐욕 지수 ${Math.round(f.score)}점, ${band.label}">
            ${bands}
            <line x1="100" y1="100" x2="${nx.toFixed(2)}" y2="${ny.toFixed(2)}" stroke="currentColor" stroke-width="3" stroke-linecap="round"/>
            <circle cx="100" cy="100" r="6" fill="currentColor" style="stroke:var(--surface)" stroke-width="2"/>
            <text x="8" y="107" font-size="9" fill="currentColor" opacity=".55">0</text>
            <text x="185" y="107" font-size="9" fill="currentColor" opacity=".55">100</text>
          </svg>
          <div class="-mt-1 text-center">
            <p class="font-mono text-3xl font-bold tabular-nums leading-none">${Math.round(f.score)}</p>
            <p class="mt-1 text-sm font-semibold">${band.label}</p>
          </div>
        </div>
        <div class="min-w-0">
          <ul class="space-y-1.5 text-sm">
            ${prevRow('전일', f.previous?.close)}${prevRow('1주 전', f.previous?.week)}${prevRow('1개월 전', f.previous?.month)}${prevRow('1년 전', f.previous?.year)}
          </ul>
          ${hist.length > 1 ? `<div class="mt-3">${sparkline(hist, { label: '공포·탐욕 지수', fmt: (v) => `${Math.round(v)} (${fgBand(v).label})`, ref: 50, refLabel: '50' })}</div>` : ''}
        </div>
      </div>
      <p class="mt-2 text-xs text-slate-500">모멘텀·주가 강도·풋/콜 비율·변동성 등 7개 지표를 0(극단적 공포)~100(극단적 탐욕)으로 합산.</p>`;
    return card('😨 CNN 공포·탐욕 지수 <span class="font-normal text-slate-400">Fear &amp; Greed</span>', f, body);
  }

  // ---------- 5. AAII sentiment survey ----------
  const AAII = [
    { key: 'bullish', label: '강세', color: 'var(--bull)' },
    { key: 'neutral', label: '중립', color: 'var(--neutral)' },
    { key: 'bearish', label: '약세', color: 'var(--bear)' },
  ];

  // AAII surveys Thursday→Wednesday (results labelled with the Wednesday) and publishes on Thursday,
  // US Eastern time. Release schedule line + a "waiting" chip once the next Thursday has come.
  const DOW = ['일', '월', '화', '수', '목', '금', '토'];
  const plusDays = (key, n) => { const d = new Date(`${key}T12:00:00Z`); d.setUTCDate(d.getUTCDate() + n); return d; };
  const md = (d) => `${d.getUTCMonth() + 1}/${d.getUTCDate()}(${DOW[d.getUTCDay()]})`;
  function aaiiSchedule(s) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s.asOf || '')) return '';
    const next = plusDays(s.asOf, 8);
    const nyToday = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York' }).format(new Date());
    const waiting = nyToday >= next.toISOString().slice(0, 10);
    return `<div class="mt-3 flex flex-wrap items-center gap-x-2 gap-y-1 rounded-xl bg-slate-50 px-3 py-2 text-xs text-slate-600 dark:bg-slate-800/60 dark:text-slate-300">
        ${ui.badge('주간 · 매주 목요일 발표', 'bg-slate-200 text-slate-700 dark:bg-slate-700/60 dark:text-slate-200')}
        <span>설문 마감 ${md(plusDays(s.asOf, 0))} · 발표 ${md(plusDays(s.asOf, 1))}</span>
        <span>·</span>
        ${waiting
          ? ui.badge(`${md(next)} 발표분 확인 중`, 'bg-amber-100 text-amber-800 dark:bg-amber-500/15 dark:text-amber-300')
          : `<span>다음 발표 <b>${md(next)}</b> <span class="text-slate-400">(미 동부 기준)</span></span>`}
      </div>`;
  }

  function aaiiCard(s) {
    if (!s || s.bullish == null) return missing('AAII 개인투자자 심리', 'aaii');
    const avg = s.averages || { bullish: 37.5, neutral: 31.5, bearish: 31.0 };
    const total = AAII.reduce((t, c) => t + (s[c.key] || 0), 0) || 100;
    // 100% stacked bar, 2px gaps, direct labels inside wide-enough segments (secondary encoding for CVD).
    const segs = AAII.map((c) => {
      const w = (s[c.key] / total) * 100;
      return `<div class="flex h-full items-center justify-center overflow-hidden text-xs font-semibold text-white first:rounded-l-lg last:rounded-r-lg"
        style="width:${w}%;background:${c.color}" data-tip="${esc(`${c.label} ${fixed(s[c.key], 1)}% · 장기평균 ${fixed(avg[c.key], 1)}%`)}">${w >= 10 ? `<span class="whitespace-nowrap px-1"><span class="hidden sm:inline">${c.label} </span>${fixed(s[c.key], 1)}%</span>` : ''}</div>`;
    }).join('');
    const legend = AAII.map((c) => {
      const diff = s[c.key] - avg[c.key];
      return `<li class="flex items-center gap-2">
        <span class="h-2.5 w-2.5 shrink-0 rounded-sm" style="background:${c.color}"></span>
        <span class="w-8 text-slate-500">${c.label}</span>
        <b class="font-mono tabular-nums">${fixed(s[c.key], 1)}%</b>
        <span class="text-xs text-slate-400">평균 ${fixed(avg[c.key], 1)} (${signed(diff, 1)}%p)</span>
      </li>`;
    }).join('');
    const spread = s.bullish - s.bearish;
    const hist = s.history || [];
    const maxAbs = Math.max(10, ...hist.map((h) => Math.abs(h.bullish - h.bearish)));
    const bars = hist.map((h) => {
      const v = h.bullish - h.bearish;
      const hPct = (Math.abs(v) / maxAbs) * 50;
      return `<div class="relative h-full flex-1" data-tip="${esc(`${shortDate(h.date)} 주 · 강세 ${fixed(h.bullish, 1)} · 중립 ${fixed(h.neutral, 1)} · 약세 ${fixed(h.bearish, 1)} → 스프레드 ${signed(v, 1)}%p`)}">
        <div class="absolute inset-x-[18%] ${v >= 0 ? 'rounded-t' : 'rounded-b'}" style="${v >= 0 ? `bottom:50%` : `top:50%`};height:${hPct}%;background:${v >= 0 ? 'var(--bull)' : 'var(--bear)'}"></div>
      </div>`;
    }).join('');
    const body = `
      <div class="mb-3 flex flex-wrap items-end gap-x-4 gap-y-1">
        <div>
          <p class="text-xs text-slate-500">강세 − 약세 스프레드</p>
          <p class="font-mono text-3xl font-bold tabular-nums leading-tight">${signed(spread, 1)}<span class="text-sm font-normal text-slate-500">%p</span></p>
        </div>
        <p class="pb-1 text-sm font-semibold">${spread >= 0 ? '▲ 강세 우위' : '▼ 약세 우위'}</p>
      </div>
      <div class="flex h-8 gap-0.5" role="img" aria-label="강세 ${fixed(s.bullish, 1)}%, 중립 ${fixed(s.neutral, 1)}%, 약세 ${fixed(s.bearish, 1)}%">${segs}</div>
      <div class="mt-4 grid gap-4 sm:grid-cols-[1fr_minmax(0,12rem)] xl:grid-cols-1">
        <ul class="space-y-1.5 text-sm">${legend}</ul>
        ${hist.length > 1 ? `<div>
          <p class="mb-1 text-xs text-slate-500">최근 ${hist.length}주 스프레드</p>
          <div class="relative flex h-16 items-stretch" role="img" aria-label="최근 ${hist.length}주 강세−약세 스프레드">
            <span class="absolute inset-x-0 top-1/2 h-px bg-slate-300 dark:bg-slate-700"></span>${bars}
          </div>
          <div class="mt-0.5 flex justify-between text-[10px] text-slate-400"><span>${esc(shortDate(hist[0].date))}</span><span>${esc(shortDate(lastOf(hist).date))}</span></div>
        </div>` : ''}
      </div>
      ${aaiiSchedule(s)}
      <p class="mt-2 text-xs text-slate-500">미국개인투자자협회(AAII) 회원 대상 주간 설문: 향후 6개월 주식시장 전망.</p>`;
    return card('🗳 AAII 개인투자자 심리 <span class="font-normal text-slate-400">Sentiment Survey</span>', s, body);
  }

  // ---------- panel ----------
  function html() {
    sparks.clear();
    const m = U.state.market;
    if (!m) return '';
    const head = `<div class="mb-3 flex flex-wrap items-end justify-between gap-2">
        <h2 class="text-base font-bold">시장 지표</h2>
        <p class="text-xs text-slate-500">${m.mock
          ? '샘플 데이터 · <code class="rounded bg-slate-100 px-1 dark:bg-slate-800">node scripts/fetch-market-data.mjs</code> 실행 시 실제 지표로 교체'
          : `${ui.staleSnapshot(m.generatedAt)} 스냅샷 ${esc(kstStamp(m.generatedAt))} KST · 평일 약 15분마다 자동 갱신 · AAII는 주간`}</p>
      </div>`;
    return `<div id="market-panel" class="relative mb-6">
      ${head}
      <div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        ${ratesCard(m.rates)}${vixCard(m.vix)}${oilCard(m.oil)}
        <div id="crypto-slot" class="contents">${cryptoCard(m.crypto)}</div>
        ${fearGreedCard(m.fearGreed)}${aaiiCard(m.aaii)}
      </div>
      <div id="mk-tip" data-chart-tip role="tooltip" class="pointer-events-none fixed z-50 hidden max-w-xs rounded-lg bg-slate-900 px-2.5 py-1.5 text-xs text-white shadow-lg dark:bg-white dark:text-slate-900"></div>
    </div>`;
  }

  // ---------- hover layer (crosshair + tooltip on sparklines, per-mark tooltip on [data-tip]) ----------
  // Generic: any view can call attachChartHover(rootEl) after rendering sparkline()/[data-tip] marks
  // inside rootEl (it needs one [data-chart-tip] element there). Returns a detach function.
  function attachChartHover(rootEl) {
    const tipEl = rootEl && rootEl.querySelector('[data-chart-tip]');
    if (!rootEl || !tipEl) return () => {};
    const showTip = (text, e) => {
      tipEl.textContent = text;
      tipEl.classList.remove('hidden');
      const r = tipEl.getBoundingClientRect();
      tipEl.style.left = `${Math.min(window.innerWidth - r.width - 8, Math.max(8, e.clientX - r.width / 2))}px`;
      tipEl.style.top = `${Math.max(8, e.clientY - r.height - 12)}px`;
    };
    const hideAll = () => {
      tipEl.classList.add('hidden');
      rootEl.querySelectorAll('[data-cross],[data-dot]').forEach((el) => el.classList.add('hidden'));
    };
    const onMove = (e) => {
      // Charts with their own hover handling (e.g. multi-series lines) opt out of this layer.
      if (e.target.closest('[data-own-hover]')) return;
      const sp = e.target.closest('[data-spark]');
      if (sp) {
        const s = sparks.get(sp.dataset.spark);
        if (!s) return;
        const rect = sp.getBoundingClientRect();
        const i = Math.round(Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width)) * (s.points.length - 1));
        const p = s.points[i];
        const xPct = (i / (s.points.length - 1)) * 100;
        const cross = sp.querySelector('[data-cross]'), dot = sp.querySelector('[data-dot]');
        cross.style.left = `${xPct}%`; cross.classList.remove('hidden');
        dot.style.left = `${xPct}%`; dot.style.top = `${s.yPct[i]}%`; dot.classList.remove('hidden');
        showTip(`${s.label} · ${p.date} · ${s.fmt(p.v)}`, e);
        return;
      }
      const t = e.target.closest('[data-tip]');
      if (t && rootEl.contains(t)) { hideAll(); showTip(t.dataset.tip, e); return; }
      hideAll();
    };
    rootEl.addEventListener('pointermove', onMove);
    rootEl.addEventListener('pointerleave', hideAll);
    return () => {
      rootEl.removeEventListener('pointermove', onMove);
      rootEl.removeEventListener('pointerleave', hideAll);
      hideAll();
    };
  }

  function mount(container) {
    unmount();
    root = container.querySelector('#market-panel');
    if (root) handlers = attachChartHover(root);
  }

  function unmount() {
    if (handlers) handlers();
    root = handlers = null;
  }

  // Swap just the Bitcoin card after a live refresh (called by app.js every minute).
  function updateCrypto() {
    const slot = root && root.querySelector('#crypto-slot');
    if (slot && U.state.market) slot.innerHTML = cryptoCard(U.state.market.crypto);
  }

  U.marketPanel = { html, mount, unmount, updateCrypto };
  // Shared chart helpers (used by the 글로벌 증시 view as well).
  U.charts = { sparkline, attachChartHover, resetSparklines: () => sparks.clear() };
})();
